G='Group stage'; R16='Round of 16'; QF='Quarter-final'; SF='Semi-final'
def run(id, win, comp, year, final, src, lvl, rounds, a=()):
    rs=[]; 
    for r,ms in rounds:
        rs.append({'r':r,'m':[{'t':{'n':o,'code':C[o]},**({'s':s} if s else {})} for o,s in ms]})
    return {'id':id,'lvl':lvl,'answer':{'n':win,'code':C[win],'a':list(a)},'comp':comp,'year':year,'final':final,'src':src,'rounds':rs}
WC='World Cup'; EU='Euros'; CA='Copa América'; AF='AFCON'; AC='Asian Cup'
